@@ -1,25 +1,37 @@
-# Graph Connectivity: Articulation Points & Bridges
+# Graph Connectivity

-Finds the **articulation points** (cut vertices) and **bridges** (cut edges) of an
-undirected graph using Tarjan's depth-first-search algorithm. Both are derived
-from the same low-link traversal in a single `O(V + E)` pass.
+Connectivity algorithms for undirected and directed graphs, all built on
+iterative Tarjan-style low-link depth-first search (each `O(V + E)`):
+
+- **Undirected:** articulation points (cut vertices) and bridges (cut edges).
+- **Directed:** strongly connected components (SCCs).
+
+Undirected connectivity and SCCs are *separate* implementations on purpose:
+articulation points/bridges and SCCs are defined on different graph types and do
+not generalize into one another (modeling an undirected graph as a directed one
+and running SCC just collapses each connected component into a single SCC). They
+share the low-link DFS technique, not an algorithm.

 ## Layout

 | File | Responsibility |
 |------|----------------|
 | `Graph.java` | Undirected graph (adjacency list) with edge identity, validation |
-| `GraphConnectivity.java` | Tarjan's algorithm; stateless, reusable, iterative |
+| `GraphConnectivity.java` | Articulation points + bridges; stateless, iterative |
 | `ConnectivityResult.java` | Result holder: articulation points + bridges |
-| `Main.java` | Runnable demo on a small example graph |
-| `GraphConnectivityTest.java` | Dependency-free test runner |
+| `DirectedGraph.java` | Directed graph (out-adjacency list), validation |
+| `StronglyConnectedComponents.java` | Tarjan's SCC algorithm; stateless, iterative |
+| `Main.java` | Runnable demo of all three analyses |
+| `GraphConnectivityTest.java` | Dependency-free test runner (undirected) |
+| `StronglyConnectedComponentsTest.java` | Dependency-free test runner (SCC) |

 ## Build and run

 ```sh
 javac -d out *.java     # compile
 java -cp out Main       # run the demo
-java -cp out GraphConnectivityTest   # run the tests (exits non-zero on failure)
+java -cp out GraphConnectivityTest            # undirected tests (exits non-zero on failure)
+java -cp out StronglyConnectedComponentsTest  # SCC tests (exits non-zero on failure)
 ```

 The demo prints:
@@ -27,6 +39,7 @@ The demo prints:
 ```
 Articulation points: 1 4
 Bridges: 0-1 1-4
+Strongly connected components: [0, 1, 2] [3] [4]
 ```

 ## Usage
@@ -42,6 +55,16 @@ result.bridges();             // [Edge[u=0, v=1, id=0], Edge[u=1, v=4, id=1]]
 `bridges()` returns the cut edges ordered by endpoints then id. Both are empty
 when the graph has none.

+For directed graphs:
+
+```java
+DirectedGraph graph = DirectedGraph.fromEdges(5, new int[][] {{1, 0}, {0, 2}, {2, 1}, {0, 3}, {3, 4}});
+List<List<Integer>> sccs = new StronglyConnectedComponents().find(graph);  // [[0, 1, 2], [3], [4]]
+```
+
+Each component lists its vertices in ascending order, and components are ordered
+by their smallest vertex, so the result is deterministic.
+
 ## Multigraphs

 Parallel edges and self-loops are supported. Edges carry a stable identity
diff --git a/StronglyConnectedComponents.java b/StronglyConnectedComponents.java
new file mode 100644
index 0000000..686437d
--- /dev/null
+++ b/StronglyConnectedComponents.java
@@ -0,0 +1,166 @@
+import java.util.ArrayDeque;
+import java.util.ArrayList;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.Comparator;
+import java.util.Deque;
+import java.util.List;
+
+/**
+ * Computes the strongly connected components (SCCs) of a directed graph using
+ * Tarjan's algorithm in a single {@code O(V + E)} pass.
+ *
+ * <p>Two vertices are in the same SCC if each is reachable from the other.
+ *
+ * <p>This is the directed-graph counterpart to the undirected
+ * {@link GraphConnectivity}; the two share the low-link DFS technique but are
+ * otherwise independent, because SCCs and articulation points/bridges are defined
+ * on different kinds of graphs.
+ *
+ * <p>Instances are stateless and therefore reusable and thread-safe: each call to
+ * {@link #find(DirectedGraph)} allocates its own traversal state. The traversal is
+ * iterative, so it handles arbitrarily deep graphs without risking a
+ * {@link StackOverflowError}.
+ */
+public final class StronglyConnectedComponents {
+
+    /**
+     * Returns the strongly connected components of the given graph.
+     *
+     * <p>Each component lists its vertices in ascending order, and the components
+     * themselves are ordered by their smallest vertex, so the result is
+     * deterministic.
+     *
+     * @param graph the directed graph to analyze
+     * @return the list of strongly connected components
+     */
+    public List<List<Integer>> find(DirectedGraph graph) {
+        return new Search(graph).run();
+    }
+
+    /**
+     * Holds the mutable Tarjan-SCC state for a single {@link #find(DirectedGraph)}
+     * invocation, keeping {@link StronglyConnectedComponents} itself stateless.
+     */
+    private static final class Search {
+
+        private static final int UNVISITED = -1;
+
+        private final DirectedGraph graph;
+
+        /** Discovery index of each vertex, or {@link #UNVISITED}. */
+        private final int[] discovery;
+
+        /** Lowest discovery index reachable from each vertex while it is on the stack. */
+        private final int[] low;
+
+        /** Whether each vertex is currently on the component stack. */
+        private final boolean[] onStack;
+
+        /** Vertices of the SCC currently being assembled, in discovery order. */
+        private final Deque<Integer> componentStack = new ArrayDeque<>();
+
+        private final List<List<Integer>> components = new ArrayList<>();
+
+        /** Monotonically increasing DFS discovery counter. */
+        private int timer;
+
+        Search(DirectedGraph graph) {
+            int vertexCount = graph.vertexCount();
+            this.graph = graph;
+            this.discovery = new int[vertexCount];
+            this.low = new int[vertexCount];
+            this.onStack = new boolean[vertexCount];
+            Arrays.fill(discovery, UNVISITED);
+        }
+
+        List<List<Integer>> run() {
+            int vertexCount = graph.vertexCount();
+            for (int v = 0; v < vertexCount; v++) {
+                if (discovery[v] == UNVISITED) {
+                    explore(v);
+                }
+            }
+
+            for (List<Integer> component : components) {
+                Collections.sort(component);
+            }
+            components.sort(Comparator.comparingInt(component -> component.get(0)));
+
+            List<List<Integer>> result = new ArrayList<>(components.size());
+            for (List<Integer> component : components) {
+                result.add(List.copyOf(component));
+            }
+            return List.copyOf(result);
+        }
+
+        /**
+         * Explores the DFS tree rooted at {@code root} with an explicit stack. When a
+         * vertex's low-link equals its own discovery index, it is the root of an SCC,
+         * and that component is popped off the component stack.
+         */
+        private void explore(int root) {
+            Deque<Frame> work = new ArrayDeque<>();
+            discover(root);
+            work.push(new Frame(root));
+
+            while (!work.isEmpty()) {
+                Frame frame = work.peek();
+                int v = frame.vertex;
+                List<Integer> outNeighbors = graph.outNeighbors(v);
+
+                if (frame.nextArc < outNeighbors.size()) {
+                    int w = outNeighbors.get(frame.nextArc++);
+                    if (discovery[w] == UNVISITED) {
+                        discover(w);
+                        work.push(new Frame(w));
+                    } else if (onStack[w]) {
+                        // Back or cross arc into a vertex still on the stack.
+                        low[v] = Math.min(low[v], discovery[w]);
+                    }
+                } else {
+                    // v is fully explored; propagate its low-link to its parent.
+                    work.pop();
+                    Frame parentFrame = work.peek();
+                    if (parentFrame != null) {
+                        low[parentFrame.vertex] = Math.min(low[parentFrame.vertex], low[v]);
+                    }
+                    if (low[v] == discovery[v]) {
+                        popComponent(v);
+                    }
+                }
+            }
+        }
+
+        private void discover(int v) {
+            discovery[v] = low[v] = timer++;
+            componentStack.push(v);
+            onStack[v] = true;
+        }
+
+        /** Pops the component stack down to and including its SCC root {@code root}. */
+        private void popComponent(int root) {
+            List<Integer> component = new ArrayList<>();
+            int w;
+            do {
+                w = componentStack.pop();
+                onStack[w] = false;
+                component.add(w);
+            } while (w != root);
+            components.add(component);
+        }
+    }
+
+    /** One vertex's state on the explicit DFS stack. */
+    private static final class Frame {
+
+        final int vertex;
+
+        /** Index of the next out-arc to follow from {@link #vertex}. */
+        int nextArc;
+
+        Frame(int vertex) {
+            this.vertex = vertex;
+        }
+    }
+}
diff --git a/StronglyConnectedComponentsTest.java b/StronglyConnectedComponentsTest.java
new file mode 100644
index 0000000..85dca70
--- /dev/null
+++ b/StronglyConnectedComponentsTest.java
@@ -0,0 +1,180 @@
+import java.util.List;
+
+/**
+ * A small, dependency-free test runner for {@link StronglyConnectedComponents}
+ * and {@link DirectedGraph}. Run with {@code java StronglyConnectedComponentsTest};
+ * it prints a summary and exits with a non-zero status if any test fails.
+ */
+public final class StronglyConnectedComponentsTest {
+
+    private int passed;
+    private int failed;
+
+    public static void main(String[] args) {
+        StronglyConnectedComponentsTest tests = new StronglyConnectedComponentsTest();
+        tests.run();
+        System.out.printf("%n%d passed, %d failed%n", tests.passed, tests.failed);
+        if (tests.failed > 0) {
+            System.exit(1);
+        }
+    }
+
+    private void run() {
+        emptyGraphHasNoComponents();
+        singleVertexIsItsOwnComponent();
+        selfLoopIsItsOwnComponent();
+        simpleCycleIsOneComponent();
+        acyclicChainIsAllSingletons();
+        cycleWithTailSplitsCorrectly();
+        nestedCyclesSplitCorrectly();
+        disconnectedGraphHandledIndependently();
+        parallelArcsDoNotChangeComponents();
+        twoVerticesNeedBothDirectionsToMerge();
+
+        negativeVertexCountIsRejected();
+        outOfRangeArcIsRejected();
+        malformedArcIsRejected();
+        analyzerIsReusableAcrossGraphs();
+
+        deepChainDoesNotOverflowTheStack();
+        deepCycleDoesNotOverflowTheStack();
+    }
+
+    private void emptyGraphHasNoComponents() {
+        check("empty graph", scc(new DirectedGraph(0)), List.of());
+    }
+
+    private void singleVertexIsItsOwnComponent() {
+        check("single vertex", scc(new DirectedGraph(1)), List.of(List.of(0)));
+    }
+
+    private void selfLoopIsItsOwnComponent() {
+        DirectedGraph graph = DirectedGraph.fromEdges(1, new int[][] {{0, 0}});
+        check("self-loop", scc(graph), List.of(List.of(0)));
+    }
+
+    private void simpleCycleIsOneComponent() {
+        DirectedGraph graph = DirectedGraph.fromEdges(3, new int[][] {{0, 1}, {1, 2}, {2, 0}});
+        check("3-cycle", scc(graph), List.of(List.of(0, 1, 2)));
+    }
+
+    private void acyclicChainIsAllSingletons() {
+        DirectedGraph graph = DirectedGraph.fromEdges(3, new int[][] {{0, 1}, {1, 2}});
+        check("acyclic chain", scc(graph), List.of(List.of(0), List.of(1), List.of(2)));
+    }
+
+    private void cycleWithTailSplitsCorrectly() {
+        // {0,1,2} form a cycle; 3 and 4 hang off it as a tail.
+        DirectedGraph graph =
+                DirectedGraph.fromEdges(5, new int[][] {{1, 0}, {0, 2}, {2, 1}, {0, 3}, {3, 4}});
+        check("cycle with tail", scc(graph),
+                List.of(List.of(0, 1, 2), List.of(3), List.of(4)));
+    }
+
+    private void nestedCyclesSplitCorrectly() {
+        // {0,1,2} cycle -> {3,4} cycle -> {5} self-loop.
+        DirectedGraph graph = DirectedGraph.fromEdges(6, new int[][] {
+                {0, 1}, {1, 2}, {2, 0}, {2, 3}, {3, 4}, {4, 3}, {4, 5}, {5, 5}});
+        check("nested cycles", scc(graph),
+                List.of(List.of(0, 1, 2), List.of(3, 4), List.of(5)));
+    }
+
+    private void disconnectedGraphHandledIndependently() {
+        // Two independent cycles with no arcs between them.
+        DirectedGraph graph = DirectedGraph.fromEdges(4, new int[][] {{0, 1}, {1, 0}, {2, 3}, {3, 2}});
+        check("disconnected cycles", scc(graph), List.of(List.of(0, 1), List.of(2, 3)));
+    }
+
+    private void parallelArcsDoNotChangeComponents() {
+        // Doubling an arc is harmless; the cycle still yields one component.
+        DirectedGraph graph =
+                DirectedGraph.fromEdges(2, new int[][] {{0, 1}, {0, 1}, {1, 0}});
+        check("parallel arcs", scc(graph), List.of(List.of(0, 1)));
+    }
+
+    private void twoVerticesNeedBothDirectionsToMerge() {
+        // A single arc 0->1 leaves them in separate components.
+        DirectedGraph graph = DirectedGraph.fromEdges(2, new int[][] {{0, 1}});
+        check("one-way arc", scc(graph), List.of(List.of(0), List.of(1)));
+    }
+
+    private void negativeVertexCountIsRejected() {
+        checkThrows("negative vertex count", IllegalArgumentException.class,
+                () -> new DirectedGraph(-1));
+    }
+
+    private void outOfRangeArcIsRejected() {
+        checkThrows("out-of-range arc", IndexOutOfBoundsException.class,
+                () -> DirectedGraph.fromEdges(2, new int[][] {{0, 5}}));
+    }
+
+    private void malformedArcIsRejected() {
+        checkThrows("malformed arc", IllegalArgumentException.class,
+                () -> DirectedGraph.fromEdges(2, new int[][] {{0}}));
+    }
+
+    private void analyzerIsReusableAcrossGraphs() {
+        StronglyConnectedComponents analyzer = new StronglyConnectedComponents();
+        DirectedGraph cycle = DirectedGraph.fromEdges(2, new int[][] {{0, 1}, {1, 0}});
+        DirectedGraph chain = DirectedGraph.fromEdges(2, new int[][] {{0, 1}});
+        check("reuse: cycle then chain (1)", analyzer.find(cycle), List.of(List.of(0, 1)));
+        check("reuse: cycle then chain (2)", analyzer.find(chain),
+                List.of(List.of(0), List.of(1)));
+    }
+
+    private void deepChainDoesNotOverflowTheStack() {
+        int vertexCount = 200_000;
+        int[][] arcs = new int[vertexCount - 1][2];
+        for (int i = 0; i < vertexCount - 1; i++) {
+            arcs[i] = new int[] {i, i + 1};
+        }
+        List<List<Integer>> components = scc(DirectedGraph.fromEdges(vertexCount, arcs));
+        boolean correct = components.size() == vertexCount
+                && components.get(0).equals(List.of(0))
+                && components.get(components.size() - 1).equals(List.of(vertexCount - 1));
+        check("deep acyclic chain of " + vertexCount, correct, true);
+    }
+
+    private void deepCycleDoesNotOverflowTheStack() {
+        int vertexCount = 200_000;
+        int[][] arcs = new int[vertexCount][2];
+        for (int i = 0; i < vertexCount; i++) {
+            arcs[i] = new int[] {i, (i + 1) % vertexCount};
+        }
+        List<List<Integer>> components = scc(DirectedGraph.fromEdges(vertexCount, arcs));
+        boolean correct = components.size() == 1 && components.get(0).size() == vertexCount;
+        check("deep cycle of " + vertexCount, correct, true);
+    }
+
+    private static List<List<Integer>> scc(DirectedGraph graph) {
+        return new StronglyConnectedComponents().find(graph);
+    }
+
+    private void check(String name, Object actual, Object expected) {
+        if (expected.equals(actual)) {
+            passed++;
+            System.out.println("PASS " + name);
+        } else {
+            failed++;
+            System.out.println("FAIL " + name + ": expected " + expected + " but was " + actual);
+        }
+    }
+
+    private void checkThrows(String name, Class<? extends Throwable> expected, Runnable action) {
+        try {
+            action.run();
+            failed++;
+            System.out.println("FAIL " + name + ": expected " + expected.getSimpleName()
+                    + " but nothing was thrown");
+        } catch (Throwable thrown) {
+            if (expected.isInstance(thrown)) {
+                passed++;
+                System.out.println("PASS " + name);
+            } else {
+                failed++;
+                System.out.println("FAIL " + name + ": expected " + expected.getSimpleName()
+                        + " but threw " + thrown.getClass().getSimpleName());
+            }
+        }
+    }
+}
